package com.ragpipeline.config;import dev.langchain4j.model.chat.ChatLanguageModel;import dev.langchain4j.model.ollama.OllamaChatModel;import org.springframework.beans.factory.annotation.Value;import org.springframework.context.annotation.*;import java.time.Duration;@Configuration public class OllamaConfig{@Bean ChatLanguageModel chat(@Value("${ollama.base-url}")String url,@Value("${ollama.model}")String model,@Value("${ollama.max-tokens}")int max,@Value("${ollama.temperature}")double temp){return OllamaChatModel.builder().baseUrl(url).modelName(model).numPredict(max).temperature(temp).timeout(Duration.ofMinutes(3)).build();}}
